package org.strongswan.android.rookstride;
import android.content.Context;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.ext.junit.runners.AndroidJUnit4;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.strongswan.android.rookstride.engine.NativeProfileStore;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class) public final class OsInventoryTest {
 String repeat(char value,int count){return new String(new char[count]).replace('\0',value);}
 final String OLD="SHA256:"+new String(new char[43]).replace('\0','A'),NEXT="SHA256:"+new String(new char[43]).replace('\0','B');
 ArrayList<Gateway> previousServers,previousPins;
 Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();
 @Before public void isolate()throws Exception{previousServers=new Vault(c).read();previousPins=new Vault(c,"ssh-identities.enc").read();new Vault(c).write(new ArrayList<>());new Vault(c,"ssh-identities.enc").write(new ArrayList<>());}
 @After public void restore()throws Exception{new Vault(c).write(previousServers);new Vault(c,"ssh-identities.enc").write(previousPins);}
 Gateway node(String host)throws Exception{Gateway n=new Gateway();n.set("host",host);n.set("fingerprint",OLD);n.set("protocol","openvpn");n.set("favorite","true");n.data.put("remember",true);n.sshPassword="fictional-admin";return n;}
 void saved(NativeProfileStore s,Gateway n)throws Exception{s.save(n.get("id"),"openvpn","Offline cleanup fixture","client\ndev tun\nproto tcp-client\nremote vpn.example.net 443\nremote-cert-tls server\nverify-x509-name vpn.example.net name\nauth-user-pass\n<ca>\nfictional-certificate\n</ca>\n");}
 void returned(Gateway n)throws Exception{n.set("osPreviousFingerprint",n.get("fingerprint"));n.set("fingerprint",NEXT);n.set("sshKeyType","ecdsa-sha2-nistp256");n.set("osReinstallState","complete");n.data.put("osReinstall",new org.json.JSONObject().put("fingerprint",NEXT));}
 @Test public void verifiedReturnClearsAllOwnedPhysicalServerProfilesButKeepsOtherServersAndImports()throws Exception{
  Gateway target=node("192.0.2.10"),sibling=node("192.0.2.10"),other=node("198.51.100.20"),imported=node("192.0.2.10");imported.data.put("clientOnly",true);NativeProfileStore store=new NativeProfileStore(c);ArrayList<Gateway> nodes=new ArrayList<>(Arrays.asList(target,sibling,other,imported));
  try{new Vault(c).write(nodes);new ServerIdentityPins(c).remember(target,OLD);for(Gateway n:nodes)saved(store,n);returned(target);OsInventory.finish(c,nodes,target);new Vault(c).write(nodes);Gateway draft=new Gateway();draft.set("host",target.get("host"));assertEquals(NEXT,new ServerIdentityPins(c).get(draft));assertEquals(3,nodes.size());assertTrue(nodes.contains(other));assertTrue(nodes.contains(imported));assertEquals("",target.get("protocol"));assertEquals("",target.get("favorite"));assertFalse(store.exists(target.get("id")));assertFalse(store.exists(sibling.get("id")));assertTrue(store.exists(other.get("id")));assertTrue(store.exists(imported.get("id")));assertEquals("fictional-admin",target.sshPassword);assertEquals(NEXT,target.get("fingerprint"));assertEquals("ecdsa-sha2-nistp256",ServerProtocols.create(target,SingleProtocols.OPENVPN).get("sshKeyType"));}
  finally{for(Gateway n:Arrays.asList(target,sibling,other,imported))store.remove(n.get("id"));}
 }
 @Test public void reinstalledExitDetachesBrokenPairAndKeepsUntouchedEntryAccess()throws Exception{
  Gateway entry=node("192.0.2.10"),exit=node("198.51.100.20"),other=node("203.0.113.30");entry.exit=exit;entry.data.put("pairReady",true);ArrayList<Gateway> nodes=new ArrayList<>(Arrays.asList(entry,other));new Vault(c).write(nodes);new ServerIdentityPins(c).remember(entry,OLD);new ServerIdentityPins(c).remember(exit,OLD);returned(exit);OsInventory.finish(c,nodes,exit);assertEquals(3,nodes.size());Gateway survivor=null;for(Gateway n:nodes)if(n.get("id").equals(entry.get("id")))survivor=n;assertNotNull(survivor);assertNull(survivor.exit);assertEquals("",survivor.get("protocol"));assertEquals("",survivor.get("favorite"));assertFalse(survivor.data.optBoolean("pairReady"));assertEquals("fictional-admin",survivor.sshPassword);assertEquals(OLD,survivor.get("fingerprint"));assertEquals("",exit.get("protocol"));assertTrue(nodes.contains(other));new Vault(c).write(nodes);assertEquals(OLD,new ServerIdentityPins(c).get(survivor));assertEquals(NEXT,new ServerIdentityPins(c).get(exit));
 }
 @Test public void verifiedReinstallCannotOverwriteAnUnrelatedCachedSshKey()throws Exception{
  Gateway target=node("192.0.2.10"),unknown=node("192.0.2.10");unknown.set("fingerprint","SHA256:"+new String(new char[43]).replace('\0','C'));new Vault(c,"ssh-identities.enc").write(new ArrayList<>(Arrays.asList(unknown)));returned(target);
  try{new ServerIdentityPins(c).replaceVerifiedOsIdentity(target);fail("An unrelated identity was overwritten");}catch(java.io.IOException expected){}
  assertEquals(unknown.get("fingerprint"),new Vault(c,"ssh-identities.enc").read().get(0).get("fingerprint"));
 }

 void administration(Gateway node,String server)throws Exception{node.set("admin","root");node.set("adminServerId",server);node.set("adminDeploymentId","old-deployment");node.data.put("adminEnabled",true).put("adminSnapshot",new org.json.JSONObject().put("old",true)).put("adminEnrollment",new org.json.JSONObject().put("old",true));}
 @Test public void verifiedCheckpointAdvancesAliasesRetiresOldAuthorityAndPreservesFreshReenrollment()throws Exception{
  Gateway entry=node("192.0.2.10"),exit=node("198.51.100.20"),alias=node("192.0.2.10"),delegated=node("192.0.2.10"),other=node("203.0.113.30");entry.exit=exit;entry.set("pairId",UUID.randomUUID().toString());alias.set("protocol","");delegated.data.put("adminAccess",true);delegated.privateKey="fictional-device-key";for(Gateway n:Arrays.asList(entry,alias,delegated))administration(n,"old-entry");administration(exit,"old-exit");administration(other,"other-server");ArrayList<Gateway> nodes=new ArrayList<>(Arrays.asList(entry,alias,delegated,other));new Vault(c).write(nodes);new ServerIdentityPins(c).remember(entry,OLD);new ServerIdentityPins(c).remember(exit,OLD);String pairId=entry.get("pairId");
  returned(entry);OsInventory.applyVerifiedIdentity(c,nodes,entry);new Vault(c).write(nodes);assertEquals(NEXT,alias.get("fingerprint"));assertEquals(NEXT,new ServerIdentityPins(c).get(alias));assertEquals(entry.get("adminServerId"),alias.get("adminServerId"));assertFalse("old-entry".equals(entry.get("adminServerId")));assertFalse("old-deployment".equals(alias.get("adminDeploymentId")));assertFalse(alias.data.has("adminSnapshot"));assertFalse(alias.data.has("adminEnrollment"));assertFalse(alias.data.optBoolean("adminEnabled"));assertEquals("root",alias.get("admin"));assertEquals("fictional-admin",alias.sshPassword);assertFalse(nodes.contains(delegated));assertTrue("Delegated record must not be converted into an owner",delegated.data.optBoolean("adminAccess"));assertEquals("old-exit",exit.get("adminServerId"));assertTrue(exit.data.optBoolean("adminEnabled"));assertEquals(OLD,new ServerIdentityPins(c).get(exit));assertEquals("other-server",other.get("adminServerId"));assertEquals(pairId,entry.get("pairId"));
  String newId=entry.get("adminServerId");entry.data.put("adminEnabled",true).put("adminSnapshot",new org.json.JSONObject().put("fresh",true));Gateway fresh=node("192.0.2.10");fresh.set("fingerprint",NEXT);fresh.data.put("adminAccess",true);fresh.set("adminServerId",newId);nodes.add(fresh);OsInventory.applyVerifiedIdentity(c,nodes,entry);assertEquals(newId,entry.get("adminServerId"));assertTrue(entry.data.optBoolean("adminEnabled"));assertTrue(entry.data.getJSONObject("adminSnapshot").getBoolean("fresh"));assertTrue("A fresh administrator must survive idempotent completion",nodes.contains(fresh));
 }
 @Test public void restoredPairKeepsItsProfileButRetiresCoexistingSetupAndOldPhysicalAdminIds()throws Exception{
  Gateway entry=node("192.0.2.10"),exit=node("198.51.100.20"),coexisting=node("192.0.2.10"),imported=node("192.0.2.10"),other=node("203.0.113.30");entry.exit=exit;entry.set("protocol","awg");exit.set("protocol","awg");entry.set("pairId",UUID.randomUUID().toString());entry.data.put("pairReady",true);imported.data.put("clientOnly",true);for(Gateway n:Arrays.asList(entry,coexisting))administration(n,"old-entry");administration(exit,"old-exit");ArrayList<Gateway> nodes=new ArrayList<>(Arrays.asList(entry,coexisting,imported,other));NativeProfileStore store=new NativeProfileStore(c);String pairId=entry.get("pairId");
  try{for(Gateway n:Arrays.asList(entry,coexisting,imported,other))saved(store,n);String saved=store.read(entry.get("id")).getString("content");new Vault(c).write(nodes);new ServerIdentityPins(c).remember(entry,OLD);new ServerIdentityPins(c).remember(exit,OLD);returned(entry);returned(exit);entry.data.put("pairedOsOperation",new org.json.JSONObject().put("phase","restored"));OsInventory.finishRestoredPair(c,nodes,entry);new Vault(c).write(nodes);
   assertEquals(pairId,entry.get("pairId"));assertTrue(entry.data.optBoolean("pairReady"));assertEquals("awg",entry.get("protocol"));assertEquals(saved,store.read(entry.get("id")).getString("content"));assertEquals("",coexisting.get("protocol"));assertFalse(store.exists(coexisting.get("id")));assertTrue(store.exists(imported.get("id")));assertTrue(store.exists(other.get("id")));assertEquals(OLD,imported.get("fingerprint"));assertEquals("fictional-admin",entry.sshPassword);assertEquals("root",entry.get("admin"));assertFalse("old-entry".equals(entry.get("adminServerId")));assertFalse("old-exit".equals(exit.get("adminServerId")));assertFalse(entry.get("adminServerId").equals(exit.get("adminServerId")));assertEquals(entry.get("adminServerId"),coexisting.get("adminServerId"));assertEquals(NEXT,new ServerIdentityPins(c).get(coexisting));assertFalse(entry.data.has("adminSnapshot"));assertFalse(entry.data.has("adminEnrollment"));
   String id=entry.get("adminServerId");entry.data.put("pairedOsOperation",new org.json.JSONObject(entry.data.getJSONObject("lastPairedOsOperation").toString()));OsInventory.finishRestoredPair(c,nodes,entry);assertEquals(id,entry.get("adminServerId"));
  }finally{for(Gateway n:Arrays.asList(entry,coexisting,imported,other))store.remove(n.get("id"));}
 }

 @Test public void verifiedMachineAdvancesOwnerAliasesOnReplayWithoutChangingOtherTrustScopes()throws Exception{
  String old=repeat('a',64),fresh=repeat('b',64),otherMachine=repeat('c',64);Gateway entry=node("192.0.2.10"),exit=node("198.51.100.20"),alias=node("192.0.2.10"),imported=node("192.0.2.10"),other=node("203.0.113.30");entry.exit=exit;for(Gateway n:Arrays.asList(entry,alias,imported))n.set("machine",old);for(Gateway n:Arrays.asList(exit,other))n.set("machine",otherMachine);imported.data.put("clientOnly",true);ArrayList<Gateway> nodes=new ArrayList<>(Arrays.asList(entry,alias,imported,other));new Vault(c).write(nodes);new ServerIdentityPins(c).remember(entry,OLD);new ServerIdentityPins(c).remember(exit,OLD);returned(entry);entry.set("machine",fresh);
  OsInventory.applyVerifiedIdentity(c,nodes,entry);assertEquals(fresh,alias.get("machine"));assertEquals(otherMachine,exit.get("machine"));assertEquals(otherMachine,other.get("machine"));assertEquals(old,imported.get("machine"));assertEquals(OLD,imported.get("fingerprint"));assertEquals(OLD,exit.get("fingerprint"));String serverId=entry.get("adminServerId");
  Gateway delegated=node("192.0.2.10");delegated.set("fingerprint",NEXT);delegated.set("machine",old);delegated.data.put("adminAccess",true);nodes.add(delegated);alias.set("machine",old);OsInventory.applyVerifiedIdentity(c,nodes,entry);assertEquals(fresh,alias.get("machine"));assertEquals(serverId,entry.get("adminServerId"));assertTrue(nodes.contains(delegated));assertEquals(old,delegated.get("machine"));assertTrue(delegated.data.optBoolean("adminAccess"));assertEquals(old,imported.get("machine"));new Vault(c).write(nodes);Gateway persisted=PairNodes.find(new Vault(c).read(),alias.get("id"));assertNotNull(persisted);assertEquals(fresh,persisted.get("machine"));
  entry.set("machine","");OsInventory.applyVerifiedIdentity(c,nodes,entry);assertEquals("",alias.get("machine"));assertEquals("",entry.get("machine"));assertEquals(old,delegated.get("machine"));assertEquals(old,imported.get("machine"));assertEquals(otherMachine,exit.get("machine"));
 }

 @Test public void unrelatedAliasPinCannotReceiveTheReplacementMachine()throws Exception{
  Gateway target=node("192.0.2.10"),alias=node("192.0.2.10");alias.set("fingerprint","SHA256:"+repeat('C',43));target.set("machine",repeat('a',64));alias.set("machine",repeat('c',64));new ServerIdentityPins(c).remember(target,OLD);returned(target);target.set("machine",repeat('b',64));ArrayList<Gateway> nodes=new ArrayList<>(Arrays.asList(target,alias));
  try{OsInventory.applyVerifiedIdentity(c,nodes,target);fail("Unrelated SSH alias must be refused before metadata changes");}catch(java.io.IOException expected){}assertEquals(repeat('c',64),alias.get("machine"));assertEquals("SHA256:"+repeat('C',43),alias.get("fingerprint"));assertEquals(OLD,new ServerIdentityPins(c).get(target));assertEquals("",target.get("adminServerId"));
 }

 @Test public void exactRestoredAwgAliasAdvancesGenerationWithoutLosingItsSavedProfile()throws Exception{
  Gateway entry=node("192.0.2.10"),exit=node("198.51.100.20"),alias=node("192.0.2.10"),unrelated=node("192.0.2.10");entry.exit=exit;for(Gateway n:Arrays.asList(entry,exit,alias,unrelated))n.set("protocol","awg");entry.set("pairEntryProtocol","awg");entry.set("pairExitProtocol","awg");entry.set("protocol","");exit.set("protocol","");entry.set("serverInstance","new-entry-instance");entry.set("osRestoredPreviousInstance","old-entry-instance");entry.set("osRestoredInstance","new-entry-instance");alias.set("serverInstance","old-entry-instance");alias.set("vpnLogin","saved-phone");alias.set("favorite","true");alias.data.put("snapshot",new org.json.JSONObject().put("instance","old-entry-instance"));unrelated.set("serverInstance","different-instance");ArrayList<Gateway> nodes=new ArrayList<>(Arrays.asList(entry,alias,unrelated));NativeProfileStore profiles=new NativeProfileStore(c);String config="[Interface]\nPrivateKey = AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=\nAddress = 10.66.0.2/32\n\n[Peer]\nPublicKey = AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=\nAllowedIPs = 0.0.0.0/0\nEndpoint = vpn.example.net:51820\n";
  try{for(Gateway n:Arrays.asList(entry,alias,unrelated))profiles.save(n.get("id"),"awg","Saved AWG fixture",config);new Vault(c).write(nodes);new ServerIdentityPins(c).remember(entry,OLD);new ServerIdentityPins(c).remember(exit,OLD);returned(entry);returned(exit);entry.data.put("pairedOsOperation",new org.json.JSONObject().put("phase","restored"));OsInventory.finishRestoredPair(c,nodes,entry);assertEquals("new-entry-instance",alias.get("serverInstance"));assertFalse("Refresh must not treat the restored identity as a new unrelated install",ServerProtocols.changedInstance(alias,"new-entry-instance"));assertEquals("saved-phone",alias.get("vpnLogin"));assertEquals("true",alias.get("favorite"));assertEquals(config,profiles.read(alias.get("id")).getString("content"));assertFalse(alias.data.has("snapshot"));assertEquals("",unrelated.get("protocol"));assertFalse(profiles.exists(unrelated.get("id")));assertTrue(profiles.exists(entry.get("id")));}
  finally{for(Gateway n:Arrays.asList(entry,alias,unrelated))profiles.remove(n.get("id"));}
 }

}
